template<
  typename ItemsT,
  typename OtherItemsT
>
bool NamesAreDisjoint(
  const std::vector<
    std::shared_ptr<ItemsT>
  >& items,
  const std::vector<
    std::shared_ptr<OtherItemsT>
  >& other_items,
  const std::wstring& shared_name
) {
  static_assert(
    std::is_base_of<types::IItem, ItemsT>::value,
    "Expected the items of items to be instances of types::IItem"
  );
  static_assert(
    std::is_base_of<types::ISomeItem, OtherItemsT>::value,
    "Expected the items of other_items to be instances of types::ISomeItem"
  );
  return (
    common::All(
      [&](const std::shared_ptr<ItemsT>& item) -> bool {
        return common::All(
          [&](const std::shared_ptr<OtherItemsT>& other_item) -> bool {
            return (
              item->name() != other_item->name()
              || item->name() == shared_name
            );
          },
          other_items
        );
      },
      items
    )
  );
}

template<
  typename ItemsT,
  typename OptionalItemsT
>
bool AliasedNamesAreUnique(
  const std::vector<
    std::shared_ptr<ItemsT>
  >& items,
  const common::optional<
    std::vector<
      std::shared_ptr<OptionalItemsT>
    >
  >& optional_items
) {
  static_assert(
    std::is_base_of<types::IItem, ItemsT>::value,
    "Expected the items of items to be instances of types::IItem"
  );
  static_assert(
    std::is_base_of<types::IItem, OptionalItemsT>::value,
    "Expected the items of optional_items to be instances of types::IItem"
  );
  const std::vector<std::shared_ptr<ItemsT> >& alias = items;
  const std::vector<std::shared_ptr<ItemsT> >& alias_of_alias = alias;
  const common::optional<std::vector<std::shared_ptr<OptionalItemsT> > >& optional_alias = optional_items;
  for (const std::shared_ptr<ItemsT>& item : alias) {
    if (types::IsSpecialItem(*item)) {
      if (std::dynamic_pointer_cast<types::ISpecialItem>(item)->level() <= 0) {
        return false;
      }
    }
  }
  return (
    (
      common::All(
        [&](const std::shared_ptr<ItemsT>& item) -> bool {
          return common::LenStr(item->name()) > 0;
        },
        alias_of_alias
      )
      && NamesAreUnique(
        alias_of_alias
      )
      && OptionalNamesAreUnique(
        optional_alias
      )
      && (
        (
          (!(optional_alias.has_value()))
          || NamesAreUnique(
            (*optional_alias)
          )
        )
      )
    )
  );
}

